entries[265100] = { ["name"] = "Frostversetzte Munition", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (20), Chemische Sprengkapsel (10), Isoliertes Kabel (15)\nStellt frostversetzte Munition her.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (35)\nKosten:\n1\n30\n\nFrostversetzte Munition\nBenutzen: Wertet dauerhaft die Munition einer Distanzwaffe auf, sodass Euer Ziel manchmal geringen Frostschaden erleidet und seine Bewegungsgeschwindigkeit für 3 Sek. um 20% verringert wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\n45" }
entries[265101] = { ["name"] = "Frostversetzte Munition", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (15), Chemische Sprengkapsel (8), Isoliertes Kabel (10)\nVerringert die erforderlichen Materialien zur Herstellung von frostversetzter Munition.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (85)\nKosten:\n5\n25\n\nFrostversetzte Munition\nBenutzen: Wertet dauerhaft die Munition einer Distanzwaffe auf, sodass Euer Ziel manchmal geringen Frostschaden erleidet und seine Bewegungsgeschwindigkeit für 3 Sek. um 20% verringert wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\n45" }
entries[265102] = { ["name"] = "Frostversetzte Munition", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (12), Chemische Sprengkapsel (5), Isoliertes Kabel (5)\nVerringert erheblich die erforderlichen Materialien zur Herstellung von frostversetzter Munition.\nVerkäufer:\nHorterin Jena\nZone:\nVol'dun\nVoldunai - Respektvoll\nKosten:\n1200\n\nFrostversetzte Munition\nBenutzen: Wertet dauerhaft die Munition einer Distanzwaffe auf, sodass Euer Ziel manchmal geringen Frostschaden erleidet und seine Bewegungsgeschwindigkeit für 3 Sek. um 20% verringert wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\n45" }
entries[265105] = { ["name"] = "Verzauberter Zwielichtzauberstab", ["text"] = "Wirken in 3 sek. 2\nReagenzien:\nZwielichtborke , Seelenstaub (4), Heiliger Splitter (2), Unsterblichkeitssplitter (8)\nOptionale Reagenzien:\nBeruf:\nVerzauberkunst der Schattenlande (15)\nLehrer:\nChiffrierer Au'vresh\nZone:\nOribos\nKosten:\n50\n\nVerzauberter Zwielichtzauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n3 - 6 Arkanschaden Geschwindigkeit 2.00\n(2.3 Schaden pro Sekunde)\n+25 Intelligenz\n+6 Ausdauer\n+ 4 Zufallswert 1\n+ 4 Zufallswert 2\nHaltbarkeit 75 / 75\n50" }
